WITH with_prev AS (SELECT *, LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) AS prev_txn_time FROM transactions), gaps AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM with_prev), sessions_transactions AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT id, txn_time, merchant, is_flagged, prev_txn_time, is_new_burst, session_id FROM sessions_transactions ORDER BY session_id NULLS FIRST;
